-- GENERADO AUTOMÁTICAMENTE por packages/training-engine/scripts/generate-demo-seed.ts. No editar a mano.
-- Planes DEMO / NO VALIDADOS: estructuras de ejemplo para probar la plataforma.
-- No constituyen prescripción profesional. Reemplazar por planes validados por el fundador.
begin;
create or replace function pg_temp.demo_session(p_id uuid, p_version uuid, p_week_id uuid, p_week int, p_n int, p_type text, p_title text, p_dur int, p_int text, p_rmin int, p_rmax int, p_main text, p_strength boolean)
returns void language sql as $f$
  insert into public.training_sessions (id, version_id, week_id, week_number, session_number, session_type, title, objective, distance_m, duration_s, intensity, rpe_min, rpe_max, warmup, main_set, cooldown, notes, progression_criteria, stop_criteria)
  values (p_id, p_version, p_week_id, p_week, p_n, p_type::public.session_type, p_title, 'Sesión de ejemplo (DEMO / NO VALIDADO).', null, p_dur, p_int::public.intensity_level, p_rmin, p_rmax,
    case when p_strength then '5 min de movilidad general.' else '10 min de caminata o trote muy suave y movilidad articular.' end, p_main,
    case when p_strength then '5 min de estiramientos suaves.' else '5–10 min de caminata suave y respiración tranquila.' end,
    'Contenido DEMO generado para pruebas. No reemplaza la indicación de un profesional.', 'Avanzá a la sesión siguiente si completaste esta dentro del rango de esfuerzo indicado y sin dolor. Si no, repetila o consultá a tu entrenador.', 'Reducí o suspendé la sesión ante dolor agudo o que aumenta, mareos, dolor en el pecho, palpitaciones o falta de aire desproporcionada. Si algún síntoma persiste, consultá a un profesional de la salud.');
$f$;

